    // 2. Compare departureTime and arrivalTime of both trips.
    String[] thisDepParts = getTrip().getDepartureTime().split(":");
    String[] thisArrParts = getTrip().getArrivalTime().split(":");
    int thisDep = Integer.parseInt(thisDepParts[0]) * 60 + Integer.parseInt(thisDepParts[1]);
    int thisArr = Integer.parseInt(thisArrParts[0]) * 60 + Integer.parseInt(thisArrParts[1]);
    
    String[] otherDepParts = trip.getDepartureTime().split(":");
    String[] otherArrParts = trip.getArrivalTime().split(":");
    int otherDep = Integer.parseInt(otherDepParts[0]) * 60 + Integer.parseInt(otherDepParts[1]);
    int otherArr = Integer.parseInt(otherArrParts[0]) * 60 + Integer.parseInt(otherArrParts[1]);
    
    // 3. Two trips overlap if their time intervals intersect (including boundaries).
